contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    receive() external payable {}

    function run(uint256 seedAmount, uint256 kiloBefore) public payable {
        require(seedAmount > 0);
        require(kiloBefore >= 500 && kiloBefore <= 30000);

        uint256 marketBefore = c.marketDrugs();
        c.seedMarket(seedAmount);
        uint256 marketAfter = c.marketDrugs();
        bool initializedAfterSeed = c.initialized();

        c.getFreeKilo();
        uint256 kiloAfterFirst = c.getMyKilo();

        bool secondReverted;
        try c.getFreeKilo() { secondReverted = false; } catch { secondReverted = true; }
        uint256 kiloAfterSecond = c.getMyKilo();

        assert(
            initializedAfterSeed == true &&
            marketAfter == seedAmount &&
            marketAfter >= marketBefore &&
            kiloAfterFirst >= kiloBefore &&
            kiloAfterSecond == kiloAfterFirst &&
            secondReverted == true
        );
    }
}

